import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { pdfTextPages, PypdfText } from '../src/lib/pdfText.js';
import { parseLabText } from '../src/lib/labParsers/index.js';

// Generated by test/makeLayoutPdfs.js; .pypdf.txt is what pypdf gives (ingestion/tools/golden.py).
const DIR = fileURLToPath(new URL('../../ingestion/tests/fixtures/pdf/', import.meta.url));
const pdfs = readdirSync(DIR).filter((f) => f.endsWith('.pdf')).sort();
// Parsers strip every line, so trailing spaces (pypdf keeps them after wrapped words) do not matter.
const norm = (t) => t.split('\n').map((l) => l.trimEnd()).join('\n');

test('pdf.js text layer matches pypdf on every layout fixture', async () => {
  assert.ok(pdfs.length >= 4);
  for (const f of pdfs) {
    const { text, pages } = await pdfTextPages(readFileSync(path.join(DIR, f)));
    assert.equal(norm(text), norm(readFileSync(path.join(DIR, f.replace(/\.pdf$/, '.pypdf.txt')), 'utf8')), f);
    assert.ok(pages.length >= 1);
  }
});

test('a generated Helix-like report parses the same from either text layer', async () => {
  const buf = readFileSync(path.join(DIR, 'rows.pdf'));
  const js = parseLabText((await pdfTextPages(buf)).text);
  const py = parseLabText(readFileSync(path.join(DIR, 'rows.pypdf.txt'), 'utf8'));
  assert.deepEqual(js, py);
  assert.equal(js.source, 'helix_pdf_v1');
  assert.deepEqual(js.observations.map((o) => [o.test_name_raw, o.result_num, o.unit_raw]), [['Гемоглобин', 132, 'г/л'], ['Лейкоциты', 6.2, '*10^9/л'], ['С-реактивный белок', 0.6, 'мг/л']]);
});

test('pypdf rules: a block that jumps through the origin starts a line, a gap of a space adds one, TJ kerning too', () => {
  const fonts = new Map([['F', { halfSpace: 125, space: 250 }]]);
  const g = (s, w = 500) => [...s].map((c) => ({ s: c, w }));
  const run = (ops) => { const x = new PypdfText(fonts); for (const [op, args] of ops) x.op(op, args); return x.result(); };
  // two cells on one baseline, each in its own BT…ET reset to the flipped origin (МКНЦ): two lines, as in pypdf
  const cell = (x, s) => [['BT'], ['Tf', ['F', 10]], ['Tm', [1, 0, 0, -1, 0, 0]], ['Td', [x, -72]], ['Tj', [g(s)]], ['ET']];
  assert.equal(run([...cell(40, 'Тест'), ...cell(200, 'Результат')]), 'Тест\nРезультат');
  // one block: Td past the end of the text plus a space width gives a space; touching text does not
  assert.equal(run([['BT'], ['Tf', ['F', 10]], ['Td', [40, 700]], ['Tj', [g('ab')]], ['Td', [20, 0]], ['Tj', [g('cd')]], ['ET']]), 'ab cd');
  assert.equal(run([['BT'], ['Tf', ['F', 10]], ['Td', [40, 700]], ['Tj', [g('ab')]], ['Td', [10, 0]], ['Tj', [g('cd')]], ['ET']]), 'abcd');
  // TJ: a kerning number at least ~ a space width inserts one
  assert.equal(run([['BT'], ['Tf', ['F', 10]], ['TJ', [[g('ab'), -300, g('cd'), -50, g('ef')]]], ['ET']]), 'ab cdef');
  // an image (Do) ends the line
  assert.equal(run([['BT'], ['Tf', ['F', 10]], ['Tj', [g('a')]], ['ET'], ['Do'], ['BT'], ['Tj', [g('b')]], ['ET']]), 'a\nb');
});

test('a non-PDF is rejected', async () => {
  await assert.rejects(pdfTextPages(Buffer.from('not a pdf')));
});
